private static void copyTweakFiles(boolean forceUpdate) {
    if (!IBConfig.get().enableDatapackSystem) {
        return;
    }
    if (!IBConfig.get().copyBundledTweaksToTacz) {
        LOGGER.info("Copia del pack default desactivada por config (copyBundledTweaksToTacz=false)");
        return;
    }
    ImmersiveBallistic.cleanupConflictingPacks();
    Path modConfigDir = Platform.getConfigFolder().resolve("immersive_ballistic");
    AmmoRulesConfig ammoRules = ImmersiveBallistic.loadOrCreateAmmoRules(modConfigDir);
    InteractionRulesConfig interactionRules = ImmersiveBallistic.loadOrCreateInteractionRules(modConfigDir);
    Path targetRoot = Platform.getGameFolder().resolve("tacz").resolve(ImmersiveBallistic.deployFolderName());
    URL sourceUrl = ImmersiveBallistic.class.getClassLoader().getResource("immersive_ballistic");
    if (sourceUrl == null) {
        LOGGER.warn("No se encontro el recurso '{}' para copiar a {}", (Object)"immersive_ballistic", (Object)targetRoot);
        return;
    }
    FileSystem jarFs = null;
    try {
        Path sourceRoot;
        URI uri = sourceUrl.toURI();
        if ("jar".equalsIgnoreCase(uri.getScheme())) {
            jarFs = FileSystems.newFileSystem(uri, Collections.emptyMap());
            sourceRoot = jarFs.getPath("immersive_ballistic", new String[0]);
        } else {
            sourceRoot = Path.of(uri);
        }
        Files.createDirectories(targetRoot, new FileAttribute[0]);
        try (Stream<Path> paths = Files.walk(sourceRoot, new FileVisitOption[0]);){
            paths.forEach(source -> ImmersiveBallistic.copyIfMissing(sourceRoot, source, targetRoot, forceUpdate, ammoRules, interactionRules));
        }
        LOGGER.info("Datapack {} en {} (detalle por archivo en nivel DEBUG)", (Object)(forceUpdate ? "sobrescrito (force update)" : "copiado (solo faltantes)"), (Object)targetRoot);
    }
    catch (IOException | URISyntaxException e) {
        LOGGER.error("No se pudo copiar '{}' hacia {}", new Object[]{"immersive_ballistic", targetRoot, e});
    }
    finally {
        if (jarFs != null) {
            try {
                jarFs.close();
            }
            catch (IOException iOException) {}
        }
    }
}

