import net.minecraftforge.fml.config.IConfigSpec;
import net.minecraftforge.fml.config.ModConfig;
import net.minecraftforge.fml.event.config.ModConfigEvent;
import net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext;
import net.minecraftforge.fml.loading.FMLEnvironment;

@Mod(value="immersive_ballistic")
public final class ImmersiveBallisticForge {
    public ImmersiveBallisticForge() {
        EventBuses.registerModEventBus((String)"immersive_ballistic", (IEventBus)FMLJavaModLoadingContext.get().getModEventBus());
        ModLoadingContext.get().registerConfig(ModConfig.Type.COMMON, (IConfigSpec)IBForgeConfig.SPEC);
        IBConfig.markLoaderManaged();
        ImmersiveBallistic.init();
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::onConfigLoad);
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::onConfigReload);
        if (FMLEnvironment.dist == Dist.CLIENT) {
            FMLJavaModLoadingContext.get().getModEventBus().register(ImmersiveBallisticForgeClient.class);
            ImmersiveBallisticClient.initClient();
        }
    }

    private void onConfigLoad(ModConfigEvent.Loading event) {
        if (event.getConfig().getSpec() != IBForgeConfig.SPEC) {
            return;
        }
        IBConfig.reload();
        ImmersiveBallistic.earlyDeploy();
    }

    private void onConfigReload(ModConfigEvent.Reloading event) {
        if (event.getConfig().getSpec() != IBForgeConfig.SPEC) {
            return;
        }
        IBConfig.reload();
    }
}

